# ---------------- A. MAG-ID string occurrences in text documents ----------------
for r in csv.DictReader(open('id_occurrences_raw.tsv'),delimiter='\t'):
    f=r['file']
    if f.endswith('.xlsx') or f.endswith('.csv') or f.endswith('.tsv'): continue   # tables handled bin-keyed below
    loc=r['loc']; m=r['match']; a=r['alias']; q=r['quote']
    if f=='papert3_070626 (2)_correction.docx':
        continue  # Table 1 rows come from table1_plan (bin-keyed)
    if f=='SPIEC-EASI_network_analysis.docx':
        if 'PAO-like MAG' in q or 'gene-content PAO-like MAGs' in q:
            add(f,loc,q,'AMBIGUOUS: ASV node label used as a MAG name',m,
                'keep ASV label "Azospira.3"; where the text asserts MAG-ness write "Azospira.3 (ASV; MAG CAN_4_bin.208 = Proximibacter.2_m)" or reword to "the Azospira.3 node"',
                'ambiguous-author',bin='CAN_4_bin.208',note='node set = ASV iterativeIDs (render_spieceasi_mag_network.py: label = ASV iterativeID); after R232 the MAG no longer shares this label')
        else:
            add(f,loc,q,'ASV (SPIEC-EASI node = 16S ASV iterativeID)',m,'(no change)','ASV-keep',
                note='ASV IDs are frozen; MAG-associated status of this node changes under NETWORK_MAG_ONLY (see PLAN risk R1)' if a in ('Azospira.3','Ignavibacteria.5','Ignavibacteria.13','Ca_Competibacter.32') else 'unchanged ID')
        continue
    if 'brief_2026-11' in f or 'program_overview' in f:
        add(f,loc,q,'ASV (16S by-day member / synthetic-genome member)',m,'(no change)','ASV-keep',
            note='Ca_Competibacter.109 = ASV (and CAN_2_bin.85 MAG id at HEAD, unchanged by R232); historical alias of coasm_bin.365 at 924fa18 only')
        continue
    add(f,loc,q,r['auto_context'],m,'see superseded policy','superseded-no-edit')

# abbreviated ID lists in SPIEC-EASI
for para,q in [(17,'two PAOs (Ca. Accumulibacter .8, .23), five GAOs (Ca. Competibacter .26/.32/.49/.51/.109) and one putative PAO (Azonexus.12)'),
               (76,'Module 1 guild MAGs: Ca. Competibacter .32, .51 (GAO)'),
               (86,'Ca. Accumulibacter.23 (PAO), Ca. Competibacter .49, .109 (GAO)'),
               (140,'all of them join a non-canonical gene-content PAO-like MAG (Azospira.3, Pseudoxanthomonas.23, Zoogloea.2) to Ca. Competibacter (.26, .32, .51)')]:
    add('SPIEC-EASI_network_analysis.docx',f'document.xml para {para}',q,'ASV labels in abbreviated list (".32" = ASV Ca_Competibacter.32, MAG coasm_bin.365 until R232)',
        '.32','(no change to ASV labels)','ASV-keep' if para!=140 else 'ambiguous-author',
        note='abbreviated forms escape a plain regex; any future MAG-id edit here would need ".32" handled explicitly')
add('SPIEC-EASI_network_analysis.docx','document.xml table 2 row 2 (Module 1, Notable flanking taxa)','Notable flanking taxa: Denitratisoma.3 (denitrifier), Taibaiella, Edaphobaculum, ...',
    'ASV (flanking non-MAG node)','Taibaiella','(no text change)','ASV-keep',bin='coasm_bin.40',
    note='after R232 coasm_bin.40 inherits ASV id Taibaiella.5, so NETWORK_MAG_ONLY would re-class this flanking node as a MAG node on any re-run (risk R1)')

# ---------------- B. taxon-name and GTDB-version occurrences in text docs ----------------
ASV_KEEP_SPIEC=('Dominant phyla','Lineages','hydrolytic Bacteroidota')
for r in csv.DictReader(open('taxa_occurrences_raw.tsv'),delimiter='\t'):
    f=r['file']
    if f in ('Table_S6_skani_novelty.tsv','Table_S7_MAG_functional_classification.csv'): continue
    if f=='paper3/papert3_071626.pdf' and r['kind']!='version': continue   # Table 1 handled bin-keyed; prose rows are manual below
    if f=='papert3_070626 (2)_correction.docx' and '"table": 1' in r['loc']: continue
    loc=r['loc']; q=r['quote']; term=r['term']; m=r['match']; kind=r['kind']
    if kind=='version':
        if 'Chaumeil' in q or 'toolkit to classify' in q or 'memory friendly' in q:
            continue  # citations stay valid
        if f in ('SERVER_HANDOFF_S6_ani_novelty.md','MANUSCRIPT_EDITS_MIMAG_rRNA_tRNA.md','novel_bacteria_supplementary.md') or f in SUPERSEDED:
            add(f,loc,q,'GTDB version/provenance (record)',m,'(no edit: historical record)','superseded-no-edit'); continue
        if re.search(r'r220|R220|2\.7\.2|release ?220',m+q[140:260]):
            ln=json.loads(loc).get('line') if f.endswith('.md') else None
            if (ln==107) or re.search(r'61 GTDB r220|bac120_msa_reps_r220|r220 bac120 mask|identify`/`align',q[100:300]):
                add(f,loc,q,'GTDB version of the Fig S4 tree INPUTS (references/markers chosen from R220)',m,'keep "r220" if Fig S4 is relabelled only; change only if the tree is rebuilt on R232','ambiguous-author')
            elif ln==181 or 'should be cited as r220' in q or 'As a caveat' in q or 'not using the reference data' in q or 'reported as such throughout' in q:
                add(f,loc,q,'GTDB version-mismatch caveat',m,'DELETE the caveat (R232 data with GTDB-Tk 2.8.0 is the supported pairing)','version-update')
            else:
                add(f,loc,q,'GTDB version / release statement',m,'GTDB-Tk v2.8.0 / GTDB R232 (see PLAN §4 for exact wording per document)','version-update')
        else:
            add(f,loc,q,'generic GTDB mention (no release named)',m,'(no change)','no-change')
        continue
    if f=='SPIEC-EASI_network_analysis.docx':
        add(f,loc,q,'ASV/16S (SILVA/MiDAS phylum name; uses Proteobacteria/Chloroflexi naming)',m,'(no change)','ASV-keep',note='SILVA keeps Patescibacteria/Myxococcota; not a GTDB label'); continue
    if 'brief_2026-11' in f:
        add(f,loc,q,'MAG (genetic-code-25 MAGs; GTDB phylum)',m,'Patescibacteriota','MAG-taxon-update',note='speaker notes only; optional (community-modelling deck)'); continue
    if f=='figures/percell_composition.pdf':
        add(f,loc,q,'MAG (Figure 1 legend: GTDB genus + phylum/class)',m,r['proposed'].split('x')[0] if term!='JJ008' else 'JJ008 (CAN_5_bin.112 stays) + new band CADEDV01 (coasm_bin.492)','regenerate-figure',
            note='re-run scripts/render_percell_composition.py after mag_quality_summary.tsv taxonomy is R232'); continue
    if f=='SERVER_HANDOFF_S6_ani_novelty.md' or f in SUPERSEDED:
        add(f,loc,q,'historical record',m,'(no edit)','superseded-no-edit'); continue
    if f in ('MANUSCRIPT_methods_results_discussion.md','papert3_070626 (2)_correction.docx','SI-paper3 (3)_correction.docx'):
        ln=json.loads(loc).get('line',-1)
        if term=='JJ008' and ln==153:
            add(f,loc,q,'MAG (focal CAN_5_bin.112, genus JJ008)',m,'(no change: CAN_5_bin.112 keeps g__JJ008 in R232)','no-change',bin='CAN_5_bin.112',
                note='only coasm_bin.492 moves JJ008->CADEDV01; plain replacement would be wrong'); continue
        if term=='JJ008' and ln==191:
            add(f,loc,q,'MAG (Figure 1 legend list, GTDB genus bands)',m,'regenerate Fig 1, then copy the new top-20 genus list (JJ008 band loses coasm_bin.492)','regenerate-figure'); continue
        if ln==191:
            add(f,loc,q,'MAG (Figure 1 legend list, GTDB genus bands)',m,{'SCMT01':'Lysobacter_I','Giesbergeria':'Simplicispira','Azospira':'Proximibacter'}.get(term,r['proposed']),'regenerate-figure',
                note='band order/membership may change; take the list from the re-rendered figure'); continue
        if term=='Azospira_A':
            add(f,loc,q,'MAG/reference (GTDB genus of CAN_4_bin.208 and its Fig S4 reference)',m,'Proximibacter (reference GCF_016858125.1 = Proximibacter restrictus in R232)','MAG-taxon-update',bin='CAN_4_bin.208'); continue
        if term=='Giesbergeria':
            add(f,loc,q,'MAG (CAN_5_bin.40 GTDB genus)',m,'Simplicispira','MAG-taxon-update',bin='CAN_5_bin.40'); continue
        if term=='sp000585075':
            add(f,loc,q,'MAG (coasm_bin.185 GTDB species)',m,'*Accumulibacter regalis* (R232 GTDB species; now agrees with the ppk1 clade IA call)','MAG-taxon-update',bin='coasm_bin.185'); continue
        if term=='Patescibacteria':
            add(f,loc,q,'MAG (GTDB phylum)',m,'Patescibacteriota','MAG-taxon-update'); continue
        if term=='Myxococcota':
            add(f,loc,q,'MAG (GTDB phylum count)',m,'Myxococcota (2), Myxococcota_A (1) -> 15 phyla (author decision: count _A as separate phylum)','number-update'); continue
    add(f,loc,q,r['auto_context'],m,r['proposed'],'review')

# ---------------- C. Table 1 (bin-keyed) ----------------
for r in csv.DictReader(open('table1_plan.tsv'),delimiter='\t'):
    col='iterativeID' if 'iterativeID' in r['location'] else ('GTDB genus' if 'genus' in r['location'] else 'GTDB lineage')
    dec='MAG-rename' if col=='iterativeID' else 'MAG-taxon-update'
    note=r['note']
    if col=='iterativeID':
        c=chg.get(r['bin'])
        if c and c['old_is_asv_id']=='True': note+='; old string stays valid as the ASV name - edit this cell only'
    add(r['file'],r['location'],f"{r['bin']} | {r['current']}",f'MAG (Table 1 row keyed by bin, {col})',r['current'],r['proposed'],dec,bin=r['bin'],note=note)

# ---------------- D. workbook / tabular cells (bin-keyed) ----------------
CUR_TAB={'MAG_target_gene_filled_UPDATED (1).xlsx','MAG_target_gene_filled.xlsx','cladeexcel.xlsx','abundance and coverage (1).xlsx',
         'Table_S6_skani_novelty.tsv','Table_S7_MAG_functional_classification.csv'}
agg=defaultdict(list); sup=Counter()
for r in csv.DictReader(open('table_cells_plan.tsv'),delimiter='\t'):
    f=r['file']
    if f not in CUR_TAB:
        sup[f]+=1; continue
    ct=r['change_type']
    if ct=='skani_or_version_cell':
        agg[(f,r['location'].split('!')[0],r['column'])].append(r); continue
    dec={'mag_id_change':'MAG-rename','mag_id_drift_only':'MAG-rename (drift fix)','taxon_rank_change':'MAG-taxon-update','taxon_rank_gain':'MAG-taxon-update',
         'lineage_change':'MAG-taxon-update','lineage_mismatch_vs_r220':'MAG-taxon-update','taxon_rank_mismatch_vs_r220':'review','header_or_note_text':'version-update'}[ct]
    note=''
    if ct=='mag_id_change':
        c=chg[r['bin']]
        note=f"id era in this file: {r['id_era']}"
        if c['old_is_asv_id']=='True': note+='; old id is also an ASV id (keep it in any ASV column)'
        if c['new_is_asv_id']=='True': note+='; new id is shared with an ASV (asv_inherit)'
    if ct=='mag_id_drift_only': note=f"6a04588-map id; HEAD id {r['proposed']} (unchanged by R232) - rewrite by bin"
    add(f,r['location'],f"{r['bin']} | {r['column']} | {r['current']}",r['context'],r['current'],r['proposed'],dec,bin=r['bin'],note=note)
for (f,sheet,col),lst in agg.items():
    add(f,f'{sheet}!column "{col}" ({len(lst)} cells)',lst[0]['current'],'MAG (R220-derived skani/ANI/reference/provenance column)',f'{len(lst)} cells','RECOMPUTE from an R232 skani search (do not hand-edit)','recompute-table',
        note='Table S6 rebuild: build_skani_novelty_291.py / build_table_s6_ani.py on R232 (see PLAN §6)')
for f,n in sup.items():
    add(f,'(whole file)','',f'superseded workbook: {n} cells would change','','(leave untouched)','superseded-no-edit')

